import { atom, read, update } from 'claude-code'
import type { Register, ToolGroupCall } from 'claude-code'

import type { Timing } from '../types'

// A folded row lists at most this many calls, the latest ones.
const MAX_ROWS = 12
const TICK_MS = 1000

// Keys a Bash call does not have; the first one a call's input holds is
// what its row shows (Read's file_path, Grep's pattern, WebFetch's url).
const TARGET_KEYS = ['file_path', 'notebook_path', 'pattern', 'path', 'query', 'url', 'description']

const timing = { plugin: 'tool-trail', key: 'timing' } as const
const tick = atom({ plugin: 'tool-trail', key: 'tick' } as const, 0)

type Summary = { label: string; detail?: string }

function oneLine(text: string): string {
  return text.replace(/\s+/g, ' ').trim()
}

function relative(path: string, cwd: string): string {
  return path.startsWith(cwd + '/') ? path.slice(cwd.length + 1) : path
}

function summarize(call: ToolGroupCall, cwd: string): Summary {
  const input = (typeof call.input === 'object' && call.input !== null ? call.input : {}) as Record<string, unknown>
  const text = (key: string) => {
    const value = input[key]
    return typeof value === 'string' && value !== '' ? oneLine(value) : undefined
  }

  if (call.tool === 'Bash') {
    const command = `$ ${text('command') ?? ''}${input.run_in_background === true ? ' &' : ''}`
    const description = text('description')
    return description === undefined ? { label: command } : { label: description, detail: command }
  }

  const target = TARGET_KEYS.map(text).find(value => value !== undefined)
  return { label: target === undefined ? call.tool : `${call.tool} ${relative(target, cwd)}` }
}

function seconds(ms: number): string {
  const s = Math.max(0, ms) / 1000
  if (s < 10) return `${s.toFixed(1)}s`
  if (s < 60) return `${Math.floor(s)}s`
  return `${Math.floor(s / 60)}m${String(Math.floor(s) % 60).padStart(2, '0')}s`
}

export const register: Register = on => {
  let isTickPending = false

  on('tool.call', async ($, e, next) => {
    const ref = { ...timing, id: e.tool_use_id }
    const startedAt = await $.clock.now()
    await $.state.set(ref, { startedAt })
    try {
      return await next(e)
    } finally {
      await $.state.set(ref, { startedAt, endedAt: await $.clock.now() })
    }
  }).catch(($, e, next) => next(e))

  // Other surfaces let the person unfold a group themselves; ctrl+o and
  // --verbose set isExpanded and already draw every call as its own row.
  on('ui.render', { component: 'ToolGroup', surface: 'terminal' }, async ($, e, next) => {
    const { calls, isExpanded } = e.props
    if (isExpanded || calls.length === 0) return next(e)

    const { Box, Text } = $.ui.resolve(e)
    const engine = await next(e)
    const cwd = await $.session.cwd()
    const now = await $.clock.now()
    const shown = calls.slice(-MAX_ROWS)
    const hidden = calls.length - shown.length
    const timings: (Timing | undefined)[] = await Promise.all(
      shown.map(async call =>
        call.tool_use_id === undefined
          ? undefined
          : (await $.state.get({ ...timing, id: call.tool_use_id })).value,
      ),
    )

    // Reading tick subscribes this row, so the timer's write redraws it.
    // A row whose calls have all ended stops reading it and stays as it is.
    if (calls.some(call => call.isRunning)) {
      await read($, tick)
      if (!isTickPending) {
        isTickPending = true
        $.clock.after(TICK_MS, () => {
          isTickPending = false
          void update($, tick, n => n + 1)
        })
      }
    }

    const rows = shown.map((call, i) => {
      const t = timings[i]
      const { label, detail } = summarize(call, cwd)
      const [mark, color] = call.isRunning
        ? ['⋯', 'warning']
        : call.isInterrupted
          ? ['⊘', 'warning']
          : call.isErrored
            ? ['✗', 'error']
            : ['✓', 'success']
      const elapsed =
        t === undefined ? '' : seconds((call.isRunning ? now : (t.endedAt ?? now)) - t.startedAt)

      return (
        <Box key={call.tool_use_id ?? String(i)}>
          <Text wrap="truncate-end">
            <Text dimColor>{i === 0 && hidden === 0 ? '⎿ ' : '  '}</Text>
            <Text color={color}>{mark}</Text>
            <Text dimColor={!call.isRunning}> {elapsed.padStart(6)} </Text>
            {label}
            {detail !== undefined && <Text dimColor>  {detail}</Text>}
          </Text>
        </Box>
      )
    })

    return (
      <Box flexDirection="column">
        {engine}
        <Box flexDirection="column" paddingLeft={2}>
          {hidden > 0 && (
            <Text dimColor>⎿ {hidden} earlier {hidden === 1 ? 'call' : 'calls'} (ctrl+o shows all)</Text>
          )}
          {rows}
        </Box>
      </Box>
    )
  })
}

