// When a tool call started and ended, in milliseconds since the epoch.
export type Timing = { startedAt: number; endedAt?: number }

declare module 'claude-code' {
  interface PluginState {
    'tool-trail': {
      // One member per call, keyed by its tool_use_id.
      timing: StateFamily<Timing>
      // Bumped once a second while a listed call runs, so its time moves.
      tick: number
    }
  }
}
